// ============================================
// CONFIG : Définir les recherches à effectuer
// ============================================

const searches = [
  {
    source: 'google_maps',
    query: 'agence digitale Paris',
    location: 'Paris, France',
    max_results: 20
  },
  {
    source: 'google_maps',
    query: 'agence marketing Lyon',
    location: 'Lyon, France',
    max_results: 20
  },
  {
    source: 'google_maps',
    query: 'startup SaaS Bordeaux',
    location: 'Bordeaux, France',
    max_results: 20
  }
];

return searches.map(s => ({ json: s }));

// Parser les résultats Google Maps
const results = $input.first().json;
const sourceQuery = $('Config Recherches').first().json.query;

if (!results.local_results || results.local_results.length === 0) {
  return [{ json: { error: 'Aucun résultat', query: sourceQuery } }];
}

return results.local_results.map(r => ({
  json: {
    company_name: r.title || '',
    company_domain: r.website ? new URL(r.website).hostname.replace('www.', '') : '',
    website: r.website || '',
    phone: r.phone || '',
    company_location: r.address || '',
    rating: r.rating || null,
    reviews: r.reviews || 0,
    company_industry: r.type || '',
    source: 'google_maps',
    source_query: sourceQuery
  }
}));

// Fusionner données entreprise + contacts Apollo
const companyData = $('Parser Résultats Maps').first().json;
const apolloResult = $input.first().json;

if (!apolloResult.people || apolloResult.people.length === 0) {
  // Pas de contacts trouvés — garder l'entreprise pour recherche manuelle
  return [{
    json: {
      ...companyData,
      first_name: '',
      last_name: '',
      email: '',
      job_title: '',
      linkedin_url: '',
      enrichment_status: 'no_contacts_found'
    }
  }];
}

return apolloResult.people.map(person => ({
  json: {
    first_name: person.first_name || '',
    last_name: person.last_name || '',
    email: person.email || '',
    email_verified: person.email_status === 'verified',
    linkedin_url: person.linkedin_url || '',
    phone: person.phone_numbers?.[0]?.raw_number || companyData.phone || '',
    job_title: person.title || '',
    company_name: companyData.company_name || person.organization?.name || '',
    company_domain: companyData.company_domain || person.organization?.primary_domain || '',
    company_size: person.organization?.estimated_num_employees?.toString() || '',
    company_industry: companyData.company_industry || person.organization?.industry || '',
    company_location: companyData.company_location || '',
    company_description: person.organization?.short_description || '',
    company_linkedin: person.organization?.linkedin_url || '',
    source: 'google_maps+apollo',
    source_query: companyData.source_query || '',
    enrichment_status: 'enriched'
  }
}));

// ============================================
// NORMALISATION + DÉDUPLICATION
// Utilise les fonctions de enrichment.js
// ============================================

function cleanName(name) {
  return name.trim().replace(/\s+/g, ' ')
    .split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' ');
}

function extractDomain(input) {
  if (!input) return '';
  if (input.includes('@')) {
    const domain = input.split('@')[1];
    const generic = ['gmail.com','yahoo.com','hotmail.com','outlook.com','orange.fr','free.fr'];
    if (generic.includes(domain)) return '';
    return domain;
  }
  try {
    const url = new URL(input.startsWith('http') ? input : 'https://' + input);
    return url.hostname.replace(/^www\./, '');
  } catch { return input; }
}

function detectSeniority(title) {
  const t = (title || '').toLowerCase();
  if (/\b(ceo|cto|cmo|founder|pdg|dg)\b/.test(t)) return 'C-Level';
  if (/\b(vp|vice)\b/.test(t)) return 'VP';
  if (/\b(directeur|director|head)\b/.test(t)) return 'Director';
  if (/\b(manager|responsable|lead)\b/.test(t)) return 'Manager';
  return 'Individual';
}

// Dédup par email
const seen = new Set();
const results = [];

for (const item of $input.all()) {
  const d = item.json;
  const key = d.email || `${d.first_name}_${d.last_name}_${d.company_name}`;
  if (seen.has(key)) continue;
  seen.add(key);

  results.push({
    json: {
      first_name: cleanName(d.first_name || ''),
      last_name: cleanName(d.last_name || ''),
      email: (d.email || '').trim().toLowerCase(),
      email_verified: d.email_verified || false,
      linkedin_url: d.linkedin_url || '',
      phone: d.phone || '',
      job_title: d.job_title || '',
      seniority: detectSeniority(d.job_title),
      company_name: d.company_name || '',
      company_domain: extractDomain(d.company_domain || d.email || ''),
      company_size: d.company_size || '',
      company_industry: d.company_industry || '',
      company_location: d.company_location || '',
      company_description: d.company_description || '',
      company_linkedin: d.company_linkedin || '',
      source: d.source || 'unknown',
      source_query: d.source_query || '',
      status: 'new',
      consent_status: 'legitimate_interest',
      opt_out: false,
      data_retention_until: new Date(Date.now() + 365*24*60*60*1000).toISOString().split('T')[0]
    }
  });
}

return results;
